public static AuthMode ModeFor(string scheme) => scheme switch
{
    "Bearer" => AuthMode.Oidc,
    "LTI" => AuthMode.Lti13,
    "ApiKey" => AuthMode.LegacyKey,
    _ => throw new ArgumentException($"Unsupported scheme '{scheme}'", nameof(scheme))
};

public enum AuthMode { Oidc, Lti13, LegacyKey }

switch (token)
{
    case { Scheme: "LTI", Version: "1.3" }:
        ValidateLti13(token);
        break;
    case { Scheme: "Bearer" } t when t.ExpiresAt > DateTimeOffset.UtcNow:
        ValidateOidc(t);
        break;
    default:
        throw new InvalidOperationException("Token not usable.");
}
